<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { messageApi } from '@/api'

const rows=ref<any[]>([]); const total=ref(0); const loading=ref(false); const types=ref<any[]>([])
const query=reactive({pageNum:1,pageSize:10,title:'',noticeType:''})
const dialogVisible=ref(false); const editId=ref<number|null>(null)
const form=reactive({title:'',content:'',noticeType:'OTHER',attachment:'',pushScope:'ALL',targetCampusIds:'',targetRoles:'',targetBuildingIds:'',isTop:0,publishTime:''})

async function load(){loading.value=true;try{const params={...query};Object.keys(params).forEach(k=>{if(params[k]===''||params[k]==null)delete params[k]});const raw:any=await messageApi.adminDraftPage(params);const body=raw?.data??raw;rows.value=body?.records??[];total.value=Number(body?.total??rows.value.length)}finally{loading.value=false}}
async function loadTypes(){const res:any=await messageApi.noticeTypes();types.value=res.data||[]}
function openCreate(){editId.value=null;Object.assign(form,{title:'',content:'',noticeType:'OTHER',attachment:'',pushScope:'ALL',targetCampusIds:'',targetRoles:'',targetBuildingIds:'',isTop:0,publishTime:''});dialogVisible.value=true}
function openEdit(row:any){editId.value=row.id;Object.assign(form,{title:row.title,content:row.content,noticeType:row.noticeType,attachment:row.attachment,pushScope:row.pushScope||'ALL',targetCampusIds:(row.targetCampusIds||[]).join(','),targetRoles:(row.targetRoles||[]).join(','),targetBuildingIds:(row.targetBuildingIds||[]).join(','),isTop:row.isTop||0,publishTime:row.publishTime||''});dialogVisible.value=true}
async function submit(){const data={...form,targetCampusIds:parseList(form.targetCampusIds),targetRoles:parseList(form.targetRoles),targetBuildingIds:parseList(form.targetBuildingIds)};try{if(editId.value===null)await messageApi.createNotice(data);else await messageApi.updateNotice(editId.value,data);ElMessage.success('保存成功');dialogVisible.value=false;load()}catch{}}
function parseList(v:any){if(Array.isArray(v))return v;return String(v||'').split(',').map((s:string)=>s.trim()).filter(Boolean)}
async function revoke(row:any){try{await messageApi.revokeNotice(row.id);ElMessage.success('已撤回');load()}catch{}}
async function remove(row:any){await ElMessageBox.confirm('确定删除该公告吗？','提示',{type:'warning'});try{await messageApi.deleteNotice(row.id);ElMessage.success('删除成功');load()}catch{}}
onMounted(()=>{load();loadTypes()})
</script>
<template><section class="hs-page"><div class="hs-page-title"><div class="cn">公告管理</div><div class="en">Notice Admin</div><div class="hs-waterline"></div></div><div class="hs-panel"><el-form inline @submit.prevent><el-form-item label="标题"><el-input v-model="query.title" clearable style="width:160px"/></el-form-item><el-form-item label="类型"><el-select v-model="query.noticeType" clearable style="width:140px"><el-option v-for="t in types" :key="t.value" :label="t.label" :value="t.value"/></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button><el-button type="primary" plain @click="openCreate">新建公告</el-button></el-form><el-table :data="rows" border stripe v-loading="loading"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="title" label="标题"/><el-table-column prop="noticeType" label="类型"/><el-table-column prop="isTop" label="置顶"><template #default="{ row }">{{ row.isTop===1?'是':'否' }}</template></el-table-column><el-table-column prop="publishTime" label="发布时间"/><el-table-column label="操作" width="170" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-button link type="warning" @click="revoke(row)">撤回</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" layout="total, prev, pager, next" @current-change="load"/></div></div><el-dialog v-model="dialogVisible" :title="editId===null?'新建公告':'编辑公告'" width="680px"><el-form :model="form" label-width="100px"><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="内容"><el-input v-model="form.content" type="textarea" :rows="6"/></el-form-item><el-form-item label="类型"><el-select v-model="form.noticeType"><el-option v-for="t in types" :key="t.value" :label="t.label" :value="t.value"/></el-select></el-form-item><el-form-item label="附件"><el-input v-model="form.attachment"/></el-form-item><el-form-item label="推送范围"><el-select v-model="form.pushScope"><el-option v-for="s in ['ALL','CAMPUS','ROLE','BUILDING']" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item label="校区ID"><el-input v-model="form.targetCampusIds" placeholder="逗号分隔"/></el-form-item><el-form-item label="角色"><el-input v-model="form.targetRoles" placeholder="逗号分隔"/></el-form-item><el-form-item label="楼栋ID"><el-input v-model="form.targetBuildingIds" placeholder="逗号分隔"/></el-form-item><el-form-item label="置顶"><el-switch v-model="form.isTop" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="发布时间"><el-date-picker v-model="form.publishTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item></el-form><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" @click="submit">保存</el-button></template></el-dialog></section></template>
<style scoped>.pager{display:flex;justify-content:flex-end;margin-top:16px}</style>